/"'^@/ { key=$0; sub(/''^@[''^{]+'"\\{/, \"\", key); sub(/,"'$/, "", key) }
/''^  title = / { title=$0; sub(/''^  title = '"\\{/, \"\", title); sub(/\\},?"'$/, "", title) }
/''^  year = / { year=$0; gsub(/[''^0-9]/, "", year); printf "%s'"\\t%s\\t%s\\n\", key, year, title }
' workspace/library/references.bib"

